"""Validate report values and requested row order, accepting equivalent CSV quoting."""
import csv
import hashlib
import json
import posixpath
from pathlib import Path

REPORTS = {'summary.csv': {'integer_columns': [], 'dash_columns': [], 'sha256': '4b8e24886523dc4b190b925e502f421c786c56df8ef83a9f30fb4d2a75e0729e'}}

for filename, rule in REPORTS.items():
    path = Path(filename)
    if not path.is_file():
        raise SystemExit(filename + ': report is missing')
    with path.open(encoding='utf-8-sig', newline='') as stream:
        rows = [[value.strip() for value in row] for row in csv.reader(stream)]
    while rows and not any(rows[-1]):
        rows.pop()
    if not rows:
        raise SystemExit(filename + ': empty report')
    for row in rows[1:]:
        for column in rule['integer_columns']:
            if column >= len(row):
                raise SystemExit(filename + ': incomplete row')
            if row[column] == '-' and column in rule['dash_columns']:
                continue
            try:
                row[column] = int(row[column])
            except ValueError:
                raise SystemExit(filename + ': expected an integer')
    for row in rows[1:]:
        if not row or row[0].startswith('/'):
            raise SystemExit(filename + ': expected a relative path')
        row[0] = posixpath.normpath(row[0])
    payload = json.dumps(rows, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    if hashlib.sha256(payload).hexdigest() != rule['sha256']:
        raise SystemExit(filename + ': report values, columns or row order differ')
print('Reports verified')
